import React, { useContext } from 'react';
import { Link } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';

const Navbar = () => {
  const { isAuthenticated, user, logout } = useContext(AuthContext);

  return (
    <nav className="flex justify-between items-center p-6 bg-[#020617] border-b border-slate-900">
      <Link to="/" className="text-blue-500 font-bold tracking-widest text-lg">AVALON</Link>
      <div className="flex gap-6 items-center text-xs uppercase font-mono">
        {!isAuthenticated ? (
          <Link to="/login" className="text-white hover:text-blue-500">Connexion</Link>
        ) : (
          <>
            {user?.role === 'admin' && <Link to="/admin" className="text-blue-500">Console Admin</Link>}
            <Link to="/dashboard" className="text-slate-300">Mon Apprentissage</Link>
            <button onClick={logout} className="text-red-500">Déconnexion</button>
            <div className="w-8 h-8 rounded-full bg-slate-800 border border-blue-500"></div>
          </>
        )}
      </div>
    </nav>
  );
};
export default Navbar;
